# Estimate from all draws on a fine grid over the displayed range.
odds_ratio_density <- function(draws, upper) {
  estimate <- stats::density(draws, from = 0, to = upper, n = 1024)
  tibble(odds_ratio = estimate$x, density = estimate$y)
}

