## ----echo = TRUE--------------------------------------------------------------
latent_f <- function(theta) {
  tl <- list(c(1,1), c(1,0), c(0,1), c(0,0))
  rs <- sample(tl, 400, replace = TRUE, prob = theta)
  do.call(rbind, rs)
}


## ----echo = TRUE--------------------------------------------------------------
 posterior_f <- function(dmat, theta) {
  sex <- dmat[,1]
  status <- dmat[,2]
  
  #Male & Admit
  x1 <- sum(sex & status)
  x2 <- sum(sex & !status)
  x3 <- sum(!sex & status)
  x4 <- sum(!sex & !status)

  x <- c(x1, x2, x3, x4)
    
  t1 <- rgamma(4, x + 1, 1)
  t1/sum(t1)
}


## ----echo = TRUE--------------------------------------------------------------
statistic_f <- function(xi, sdp, i) {
  n <- length(sdp) %/% 2
  sum(xi == sdp[c(i, n + i)])
}


## ----echo = TRUE--------------------------------------------------------------
mechanism_f <- function(sdp, sx) {
  sx * log(3/4) + (length(sdp) - sx) * log(1/4)
}


