## ----echo = TRUE--------------------------------------------------------------
statistic_f <- function(xi, sdp, i) {
  if(xi[1] & xi[2]) {
    c(1,0,0,0)
  } else if (xi[1] & !xi[2]) {
    c(0,1,0,0)
  } else if (!xi[1] & xi[2]) {
    c(0,0,1,0)
  } else {
    c(0,0,0,1)
  }
}


## ----echo = TRUE--------------------------------------------------------------
mechanism_f <- function(sdp, sx) {
  sum(dapper::ddnorm(sdp - sx, mu = 0, sigma = 6.32, log = TRUE))
}


## ----echo = FALSE-------------------------------------------------------------
library(dapper)

dmod <- new_privacy(posterior_f = posterior_f,
                    latent_f    = latent_f,
                    mechanism_f = mechanism_f,
                    statistic_f = statistic_f,
                    npar     = 4,
                    varnames = names(sdp_dg))

dp_out <- dapper_sample(dmod,
                  sdp = sdp_dg,
                  seed = 123,
                  niter = 2000,
                  warmup = 1000,
                  chains = 1,
                  init_par = rep(.25,4))


## ----echo = TRUE--------------------------------------------------------------
summary(dp_out)


