privatized data. Solid lines denote privacy-aware inference using dapper; dashed
lines denote naïve inference that treats the privatized data as noise-free.
The privacy-aware posterior closely resembles the posterior obtained from the confidential data."

table_post <- function(x) {
    t1 <- rgamma(4, x + 1, 1)
    t1/sum(t1)
}

set.seed(1)
confidential_data <- c(t(adm_cnf))
cps <- t(sapply(1:1000, function(s) table_post(confidential_data)))
odds_female   <- cps[,1] / cps[,2]
odds_male <- cps[,3] / cps[,4]
odds_ratio_conf  <- odds_male/odds_female

set.seed(1)
sdp <- c(t(adm_prv))
cps <- t(sapply(1:1000, function(s) table_post(sdp)))
odds_female   <- cps[,1] / cps[,2]
odds_male <- cps[,3] / cps[,4]
odds_ratio_noisy  <- odds_male/odds_female

df1 <- tibble(Confidential = odds_ratio_conf, Privatized = odds_ratio_noisy) %>%
  pivot_longer(everything(), names_to = "data", values_to = "odds_ratio") %>%
  mutate(analysis = "Naïve")

df2 <- tibble(Confidential = odds_ratio_conf, Privatized = or2) %>%
  pivot_longer(everything(), names_to = "data", values_to = "odds_ratio") %>%
  mutate(analysis = "Privacy-aware")

df <- rbind(df1,df2) %>%
  mutate(analysis = factor(analysis, levels = names(analysis_linetypes)))

df_density <- df %>%
  group_by(data, analysis) %>%
  group_modify(~ odds_ratio_density(.x$odds_ratio, upper = 8)) %>%
  ungroup()

ggplot(df_density, aes(odds_ratio, density, group = interaction(data, analysis),
                      fill = data, color = data, linetype = analysis)) +
  geom_ribbon(
    aes(ymin = 0, ymax = density),
    alpha = .25,
    color = NA,
    show.legend = c(fill = TRUE, colour = FALSE, linetype = FALSE)
  ) +
  geom_line(
    linewidth = .7,
    key_glyph = ggplot2::draw_key_path,
    show.legend = c(fill = FALSE, colour = FALSE, linetype = TRUE)
  ) +
  facet_wrap(~analysis) +
  coord_cartesian(xlim = c(0, 8)) +
  labs(x = "Odds Ratio", y = "Density") +
  paper_theme +
  comparison_legend_theme +
  scale_fill_manual(name = "Data", values = lancet_colors) +
  scale_color_manual(name = "Data", values = lancet_colors) +
  scale_linetype_manual(name = "Analysis", values = analysis_linetypes) +
  guides(color = "none",
         fill = guide_legend(order = 1, title.position = "left", nrow = 1),
         linetype = guide_legend(order = 2, title.position = "left", nrow = 1,
                                 override.aes = list(fill = NA, color = "black")))


## ----echo = TRUE--------------------------------------------------------------
latent_f <- function(theta) {
  xmat <- MASS::mvrnorm(50 , mu = c(.9,-1.17), Sigma = diag(2))
  y <- cbind(1,xmat) %*% theta + rnorm(50, sd = sqrt(2))
  cbind(y,xmat)
}


## ----echo = TRUE--------------------------------------------------------------
posterior_f <- function(dmat, theta) {
  x <- cbind(1,dmat[,-1])
  y <- dmat[,1]

  ps_s2 <- solve((1/2) * t(x) %*% x + (1/4) * diag(3))
  ps_m <- ps_s2 %*% (t(x) %*% y) * (1/2)

  MASS::mvrnorm(1, mu = ps_m, Sigma = ps_s2)
}


## ----echo = TRUE--------------------------------------------------------------
clamp_data <- function(dmat) {
  pmin(pmax(dmat,-10),10) / 10
}

statistic_f <- function(xi, sdp, i) {
  xic <- clamp_data(xi)
  ydp <- xic[1]
  xdp <- cbind(1,t(xic[-1]))
    
  s1 <- t(xdp) %*% ydp
  s2 <- t(ydp) %*% ydp
  s3 <- t(xdp) %*% xdp

  ur_s1 <- c(s1)
  ur_s2 <- c(s2)
  ur_s3 <- s3[upper.tri(s3,diag = TRUE)][-1]
  c(ur_s1,ur_s2,ur_s3)
}


## ----echo = TRUE--------------------------------------------------------------
mechanism_f <- function(sdp, sx) {
  sum(VGAM::dlaplace(sdp - sx, 0, 15/10, log = TRUE))
}


## ----echo = TRUE--------------------------------------------------------------
deltaa <- 15
epsilon <- 10
n <- 50

set.seed(1)
xmat <- MASS::mvrnorm(n, mu = c(.9,-1.17), Sigma = diag(2))
beta <- c(-1.79, -2.89, -0.66)
y <- cbind(1,xmat) %*% beta + rnorm(n, sd = sqrt(2))

#clamp the confidential data in xmat
dmat <- cbind(y,xmat)
sdp <- apply(
  sapply(seq_len(nrow(dmat)), 
  function(i) {
    statistic_f(dmat[i, ], NULL, i)
  }),
  1,
  sum
)

#add Laplace noise 
sdp <- sdp + VGAM::rlaplace(length(sdp), location = 0, scale = deltaa/epsilon)


## ----echo = TRUE--------------------------------------------------------------
library(dapper)
set.seed(123)

dmod <- new_privacy(posterior_f = posterior_f,
                    latent_f    = latent_f,
                    mechanism_f = mechanism_f,
                    statistic_f = statistic_f,
                    npar     = 3,
                    varnames = c("beta0", "beta1", "beta2"))



dp_out <- dapper_sample(dmod,
                        sdp = sdp,
                        niter = 25000,
                        warmup = 1000,
                        chains = 1,
                        init_par = rep(0,3))



## ----echo = TRUE--------------------------------------------------------------
summary(dp_out)


## ----echo = TRUE--------------------------------------------------------------
#x^Ty
s1 <- sdp[1:3]

#y^Ty
s2 <- sdp[4]

#x^Tx
s3 <- matrix(0, nrow = 3, ncol = 3)
s3[upper.tri(s3, diag = TRUE)] <- c(n, sdp[5:9])
s3[lower.tri(s3)] <- s3[upper.tri(s3)]


## ----echo = TRUE--------------------------------------------------------------
s3_inverse <- pracma::nearest_spd(solve(s3))
parameter_scale <- diag(c(10, 1, 1))

bhat_scaled <- s3_inverse %*% s1
sigma_hat_scaled <- (2 / 10^2) * s3_inverse

bhat <- parameter_scale %*% bhat_scaled
sigma_hat <- parameter_scale %*% sigma_hat_scaled %*% parameter_scale


