## ----ppc-yty-setup, include=FALSE---------------------------------------------
simulate_private_yty <- function(theta_draw) {
  replicated_data <- latent_f(theta_draw)
  replicated_statistic <- apply(
    sapply(seq_len(nrow(replicated_data)), function(i) {
      statistic_f(replicated_data[i, ], sdp, i)
    }),
    1,
    sum
  )

  replicated_statistic[4] + VGAM::rlaplace(
    1,
    location = 0,
    scale = deltaa / epsilon
  )
}

